//                             In The Name Of Allah                                           
//                             	Mohammad Hosseini
#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using pii = pair<ll, ll>;

const ll MOD = 1e9 + 7;
const int MAX_D = 64, MAX_LOG = 65;

ll n, d;
vector<ll> digits;

struct Node {
    ll dp[MAX_D][MAX_D], cnt[MAX_D][MAX_D];
    bool mark[MAX_D], temp[MAX_D];

    void merge(const Node& other) {
        memset(cnt, 0, sizeof(cnt));
        for (int i = 0; i <= d; ++i) {
            for (int j = 0; j <= d; ++j) {
                for (int k = 0; k <= d; ++k) {
                    cnt[i][j] = (cnt[i][j] + dp[k][j] * other.dp[i][k]) % MOD;
                }
            }
        }
        for (int i = 0; i < d; ++i) {
            if (mark[i] && !other.mark[i]) {
                for (int j = 0; j <= d; ++j)
                    cnt[i][j] = dp[i][j];
            }
            if (!mark[i] && other.mark[i]) {
                for (int j = 0; j <= d; ++j)
                    cnt[j][i] = other.dp[j][i];
            }
            mark[i] |= other.mark[i];
        }
        memcpy(dp, cnt, sizeof(dp));
    }

    void clear() {
        memset(dp, 0, sizeof(dp));
        memset(cnt, 0, sizeof(cnt));
    }

    void shift(int x) {
        memset(cnt, 0, sizeof(cnt));
        for (int i = 0; i < d; ++i) {
            for (int j = 0; j < d; ++j) {
                cnt[(i + x) % d][(j + x) % d] = dp[i][j];
            }
            cnt[(i + x) % d][d] = dp[i][d];
        }
        for (int i = 0; i < d; ++i) {
            cnt[d][(i + x) % d] = dp[d][i];
        }
        cnt[d][d] = dp[d][d];
        memcpy(dp, cnt, sizeof(dp));
        for (int i = 0; i < d; ++i) {
            temp[i] = mark[(i + x) % d];
        }
        memcpy(mark, temp, sizeof(mark));
    }
} segmentTree[MAX_LOG], prefixTree[MAX_LOG], tempNode;

Node getPrefixNode(ll x) {
    ll h = x, power = 1, level = -1;
    while (h >= d) {
        h /= d;
        power *= d;
        ++level;
    }
    x %= power;
    if (level == -1) return prefixTree[h];
    Node result = segmentTree[level];
    tempNode = segmentTree[level];
    for (int i = 1; i < h; ++i) {
        tempNode.shift(1);
        result.merge(tempNode);
    }
    tempNode = getPrefixNode(x);
    tempNode.shift(h);
    result.merge(tempNode);
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    cin >> n >> d;
    --n;
    ll original = n;
    while (n > 0) {
        digits.push_back(n % d);
        n /= d;
    }

    prefixTree[0].dp[d][d] = 2;
    prefixTree[0].dp[d][0] = -1;
    prefixTree[0].dp[0][d] = 1;
    prefixTree[0].mark[0] = true;
    segmentTree[0] = prefixTree[0];

    for (int i = 1; i < d; ++i) {
        prefixTree[i].dp[d][d] = 2;
        prefixTree[i].dp[d][i] = -1;
        prefixTree[i].dp[i][d] = 1;
        prefixTree[i].mark[i] = true;
        segmentTree[0].merge(prefixTree[i]);
        prefixTree[i] = segmentTree[0];
    }

    for (int level = 1; level <= (int)digits.size(); ++level) {
        segmentTree[level] = segmentTree[level - 1];
        tempNode = segmentTree[level - 1];
        for (int j = 1; j < d; ++j) {
            tempNode.shift(1);
            segmentTree[level].merge(tempNode);
        }
    }

    Node answer = getPrefixNode(original);
    cout << answer.dp[d][d] << '\n';

    return 0;
}
